#!/usr/bin/env node
/**
 * Drive the original Decision studies extension with a retained experiment or diagnostic.
 * Requires Playwright/Chromium and an explicit operator decision-configuration JSON.
 * No model outcomes or paired experiment cells are generated by this script.
 */
import { chromium } from 'playwright';
import { mkdir, readFile, writeFile, rename } from 'node:fs/promises';
import { resolve, join, relative, basename } from 'node:path';
import { createHash } from 'node:crypto';
import { parseArgs } from 'node:util';

const { values: args } = parseArgs({ options: {
  url: { type: 'string' }, 'url-file': { type: 'string' }, workspace: { type: 'string' },
  experiment: { type: 'string' }, diagnostic: { type: 'string' }, 'report-sha256': { type: 'string' },
  configuration: { type: 'string' }, output: { type: 'string' },
  'receiving-receipt': { type: 'string' },
  objective: { type: 'string', default: 'worst_case' }, 'time-limit': { type: 'string', default: '60' },
  'run-label': { type: 'string' }, 'browser-channel': { type: 'string' },
  'delivery-profile': { type: 'string' }, 'delivery-point': { type: 'string' },
  'delivery-budgets': { type: 'string' },
  headed: { type: 'boolean', default: false }, video: { type: 'boolean', default: false },
  help: { type: 'boolean', default: false },
} });
if (args.help) {
  process.stdout.write('Usage: node source/run_robust_workbench_browser.mjs --url-file PRIVATE_URL_FILE (--experiment RETAINED_EXPERIMENT_ID | --diagnostic RETAINED_DIAGNOSTIC_ID --report-sha256 EXACT_REPORT_SHA256) --configuration DECISION_CONFIG_JSON [--workspace OPERATOR_WORKSPACE_KEY] [--output DIRECTORY] [--objective worst_case|minimax_regret|expected] [--time-limit SECONDS] [--delivery-profile NATIVE_PROFILE_ID [--delivery-point ZERO_BASED_INDEX --delivery-budgets EXPLICIT_COMMA_SEPARATED_BUDGETS]] [--video] [--headed]\nDecision configuration supplies actual candidate/profile/metric IDs, costs, capacity use, cost units, metric scales and weights. Optional ceilings, targets, probabilities and group limits are honored. Outcome cells come from the selected original retained experiment or diagnostic. Diagnostic mode pins the exact report SHA and honors source.diagnostic_design structural choices. Optional delivery mode opens the original atlas using an explicit native profile, checks its original run pair, backlink and retained mobile draft. An explicit frontier point also requires explicit delivery budgets; it is calculated through the original frontier action.\n');
  process.stdout.write('Receiving: --url-file PRIVATE_URL_FILE --receiving-receipt NATIVE_RECEIVING_JSON [--output DIRECTORY] [--video]. Reopens the exact restored saved calculation and completed map/client release, original file tickets, source backlink and 390px draft without another preparation or calculation.\n');
  process.exit(0);
}
const runLabel = args['run-label'] || new Date().toISOString().replace(/[:.]/g, '-');
const output = resolve(args.output || join('artifacts', 'decision-studies', runLabel));
const journal = {
  schema: 'upstate.robust-workbench-journey/v1', started_at: new Date().toISOString(),
  prepared_by: 'TokenJunkieLabs engineering', status: 'running',
  experiment_id: args.experiment || null, diagnostic_id: args.diagnostic || null,
  diagnostic_report_sha256: args['report-sha256'] || null, objective: args.objective,
  steps: [], screenshots: [], exports: [], browser_errors: [],
};
let browser, context, page, privateURL = '', origin = '', capability = '';
const taskCache = new Map(), taskWaiters = new Map();
const clone = value => JSON.parse(JSON.stringify(value));
function canonical(value) {
  if (Array.isArray(value)) return '[' + value.map(canonical).join(',') + ']';
  if (value && typeof value === 'object') return '{' + Object.keys(value).sort().map(key => JSON.stringify(key) + ':' + canonical(value[key])).join(',') + '}';
  return JSON.stringify(value);
}
function requireValue(condition, message) { if (!condition) throw Error(message); }
function redact(value) {
  let result = String(value);
  for (const secret of [privateURL, capability, origin].filter(Boolean)) result = result.split(secret).join('[private operator]');
  return result.replace(/#token=[^\s"'<>]+/g, '#token=[redacted]');
}
function bodyOf(response) { try { return response.request().postDataJSON() || {}; } catch { return {}; } }
function matches(path, criteria = {}) {
  return response => new URL(response.url()).pathname === path &&
    Object.entries(criteria).every(([key, value]) => bodyOf(response)[key] === value);
}
async function nativeJSON(response, label) {
  requireValue(response.ok(), label + ' returned HTTP ' + response.status());
  const value = await response.json();
  requireValue(!value.error, label + ': ' + redact(value.error?.message || value.error || ''));
  return value;
}
function retainTask(task) {
  if (!task?.id) return;
  const old = taskCache.get(task.id);
  if (old?.state === 'complete' && task.state !== 'complete') return;
  taskCache.set(task.id, task);
  for (const callback of taskWaiters.get(task.id) || []) callback(task);
}
async function observeResponse(response) {
  const path = new URL(response.url()).pathname;
  if (!response.ok() || !['/api/state', '/api/task', '/api/actions'].includes(path)) return;
  try {
    const value = await response.json();
    if (path === '/api/state') for (const task of value.tasks || []) retainTask(task);
    else retainTask(value);
  } catch {}
}
async function waitTask(id, allowance = 180000) {
  return new Promise((resolveTask, rejectTask) => {
    const callbacks = taskWaiters.get(id) || new Set();
    const finish = (error, value) => {
      clearTimeout(timer); callbacks.delete(onTask);
      if (!callbacks.size) taskWaiters.delete(id);
      error ? rejectTask(error) : resolveTask(value);
    };
    const onTask = task => {
      if (task.state === 'complete') finish(null, task);
      else if (['failed', 'interrupted'].includes(task.state)) finish(Error('Native operation ' + id + ' is ' + task.state + ': ' + redact(typeof task.error === 'string' ? task.error : JSON.stringify(task.error || {}))));
    };
    const timer = setTimeout(() => finish(Error('Native operation ' + id + ' did not finish within its browser journey allowance. Its original task remains retained.')), allowance);
    callbacks.add(onTask); taskWaiters.set(id, callbacks);
    if (taskCache.has(id)) onTask(taskCache.get(id));
  });
}
async function action(selector, name, allowance) {
  const pending = page.waitForResponse(matches('/api/actions', { action: name }));
  await page.locator(selector).click();
  const response = await pending, request = bodyOf(response);
  const queued = await nativeJSON(response, name);
  requireValue(queued.id, name + ' did not return its original task ID.');
  retainTask(queued);
  const task = await waitTask(queued.id, allowance);
  journal.steps.push({ action: name, task_id: task.id, operation_id: request.operation_id,
    state: task.state, study_id: task.result?.id || task.result?.study_id || request.payload?.study_id || null,
    revision: task.result?.revision ?? request.payload?.revision ?? null, run_id: task.result?.run_id || null });
  return { task, request };
}
async function ready() {
  const nav = page.locator('[data-view="robust-workbench"]');
  await nav.waitFor({ state: 'visible' });
  if (!(await page.locator('.robust-workbench #rw-studies').isVisible())) {
    const pending = page.waitForResponse(matches('/api/robust-workbench/catalog'));
    await nav.click(); await nativeJSON(await pending, 'Decision-study catalog');
  }
  await page.locator('.robust-workbench #rw-studies').waitFor({ state: 'visible' });
  await page.waitForFunction(() => !/^(Reading|Opening)/.test(document.querySelector('#rw-status')?.textContent || ''));
}
async function changeWorkspace(id) {
  if (await page.locator('#workspace-select').inputValue() === id) return;
  const pending = page.waitForResponse(async response => {
    if (new URL(response.url()).pathname !== '/api/state' || !response.ok()) return false;
    try { return (await response.json()).workspace_key === id; } catch { return false; }
  });
  await page.locator('#workspace-select').selectOption(id); await pending; await ready();
}
async function findSource() {
  if (args.workspace) await changeWorkspace(args.workspace);
  await ready();
  const selector = args.diagnostic ? '#rw-diagnostics option' : '#rw-experiments option';
  const sourceId = args.diagnostic || args.experiment;
  const available = async () => page.locator(selector).evaluateAll((nodes, id) =>
    nodes.some(node => node.value === id && !node.disabled), sourceId);
  if (await available()) return;
  if (!args.workspace) {
    const choices = await page.locator('#workspace-select option').evaluateAll(nodes =>
      nodes.filter(node => node.value && !node.disabled).map(node => node.value));
    for (const id of choices) { await changeWorkspace(id); if (await available()) return; }
  }
  throw Error('The requested retained ' + (args.diagnostic ? 'diagnostic report' : 'experiment with its original summary') + ' was not found in the operator workspace choices.');
}
async function shot(name, focus) {
  if (focus) await page.locator(focus).scrollIntoViewIfNeeded();
  const path = join(output, name + '.png');
  await page.screenshot({ path, fullPage: !focus, animations: 'disabled' });
  journal.screenshots.push(relative(output, path));
}
function number(value, label, { positive = false, optional = false, nonnegative = false } = {}) {
  if (optional && (value === null || value === undefined)) return null;
  requireValue(typeof value === 'number' && Number.isFinite(value), 'Supply a finite numeric ' + label + ' in the decision configuration.');
  requireValue(!positive || value > 0, label + ' must be positive.');
  requireValue(!nonnegative || value >= 0, label + ' must be nonnegative.');
  return value;
}
function prepareConfiguration(native, supplied) {
  requireValue(supplied && typeof supplied === 'object' && !Array.isArray(supplied), 'Decision configuration must be a JSON object.');
  const accepted = new Set(['schema_version', 'title', 'mode', 'additive_basis', 'metrics', 'candidates', 'profiles', 'budget', 'cost_units', 'capacity', 'group_limits', 'source', 'notes']);
  for (const key of Object.keys(supplied)) requireValue(accepted.has(key), 'Unsupported decision configuration field: ' + key + '. Outcome cells must come from the retained native source.');
  for (const key of ['schema_version', 'mode', 'additive_basis']) if (key in supplied) requireValue(canonical(supplied[key]) === canonical(native[key]), 'The configuration changes the native ' + key + '.');
  if (supplied.source) for (const [key, value] of Object.entries(native.source || {})) {
    if (key === 'diagnostic_design') continue;
    if (key in supplied.source) requireValue(canonical(supplied.source[key]) === canonical(value), 'The configuration source does not match the retained ' + key + '.');
  }
  const result = clone(native);
  if (native.source?.diagnostic_id) {
    const choice = supplied.source?.diagnostic_design ?? native.source.diagnostic_design;
    requireValue(choice && ['single_group', 'explicit_structural_ensemble'].includes(choice.structural_mode),
      'Choose a declared diagnostic structural mode.');
    requireValue(typeof choice.structural_reason === 'string', 'Supply the diagnostic structural comparison reason as text.');
    if (choice.structural_mode === 'explicit_structural_ensemble') requireValue(choice.structural_reason.trim(),
      'Describe the explicit structural-model ensemble in source.diagnostic_design.structural_reason.');
    result.source.diagnostic_design = {
      structural_mode: choice.structural_mode, structural_reason: choice.structural_reason.trim(),
    };
  }
  result.title = (supplied.title || native.title) + ' · working decision · ' + runLabel;
  requireValue(typeof supplied.cost_units === 'string' && supplied.cost_units.trim(), 'Supply explicit cost_units in the decision configuration.');
  result.cost_units = supplied.cost_units.trim();
  result.budget = number(supplied.budget, 'budget ceiling', { optional: true, nonnegative: true });
  result.capacity = number(supplied.capacity, 'capacity ceiling', { optional: true, nonnegative: true });
  result.group_limits = clone(supplied.group_limits || {});
  requireValue(result.group_limits && typeof result.group_limits === 'object' && !Array.isArray(result.group_limits), 'group_limits must be an object.');
  result.notes = supplied.notes || '';
  for (const key of ['metrics', 'candidates', 'profiles']) {
    requireValue(Array.isArray(supplied[key]) && supplied[key].length > 0, 'Supply the actual included ' + key + ' in the decision configuration.');
    const seen = new Set();
    result[key] = supplied[key].map(input => {
      requireValue(input && typeof input.id === 'string' && !seen.has(input.id), key + ' must have unique retained IDs.');
      seen.add(input.id);
      const base = native[key].find(row => row.id === input.id);
      requireValue(base, 'Unknown retained ' + key + ' ID: ' + input.id);
      const row = clone(base);
      if (input.units !== undefined) requireValue(input.units === base.units, input.id + ' units differ from the original native metric.');
      if (key === 'metrics') {
        row.scale = number(input.scale, input.id + ' scale', { positive: true });
        row.weight = number(input.weight, input.id + ' weight', { nonnegative: true });
        row.guaranteed_gain = number(input.guaranteed_gain, input.id + ' guaranteed gain', { optional: true });
      } else if (key === 'candidates') {
        row.cost = number(input.cost, input.id + ' cost', { nonnegative: true });
        row.capacity = number(input.capacity, input.id + ' capacity use', { nonnegative: true });
        row.group = input.group ?? null;
        for (const field of ['required', 'excluded']) {
          requireValue(input[field] === undefined || typeof input[field] === 'boolean', input.id + ' ' + field + ' must be boolean.');
          row[field] = input[field] ?? false;
        }
      } else row.probability = number(input.probability, input.id + ' probability', { optional: true, nonnegative: true });
      return row;
    });
  }
  result.cells = [];
  return result;
}
async function opened(document) {
  await page.waitForFunction(expected => {
    const selected = document.querySelector('#rw-studies')?.value;
    return selected === expected.id && Number(document.querySelector('#rw-openRevision')?.value) === expected.revision &&
      document.querySelector('#rw-title')?.value === expected.title;
  }, { id: document.id, revision: document.revision, title: document.study.title });
}
async function openStudy(id) {
  const pending = page.waitForResponse(matches('/api/robust-workbench/study', { study_id: id }));
  await page.locator('#rw-studies').selectOption(id);
  const record = await nativeJSON(await pending, 'Reopen native study'); await opened(record); return record;
}
async function exportFile(selector, name, extension) {
  const { task } = await action(selector, name);
  const row = page.locator('[data-rw-task-id=' + JSON.stringify(task.id) + ']');
  const link = row.locator('a').filter({ hasText: new RegExp(extension + '\\b', 'i') });
  let chosen = link.first();
  if (!await link.count()) chosen = row.locator('a').first();
  await chosen.waitFor({ state: 'visible' });
  const pending = page.waitForEvent('download'); await chosen.click(); const download = await pending;
  const filename = task.id + '-' + basename(download.suggestedFilename());
  const path = join(output, 'exports', filename); await download.saveAs(path);
  const bytes = await readFile(path);
  requireValue(bytes.length > 0, 'The native ' + name + ' export is empty.');
  const record = { action: name, task_id: task.id, file: relative(output, path), bytes: bytes.length, sha256: createHash('sha256').update(bytes).digest('hex') };
  journal.exports.push(record);
  return { path, bytes, task };
}

async function exerciseNativeDelivery(saved, solved, allowance, retained = null) {
  if (!args['delivery-profile']) return;
  const profileId = args['delivery-profile'];
  let calculation = retained ? { run_id: retained.run.id, revision: retained.run.revision,
    answer: retained.run.result } : solved.task.result;
  let pointIndex = retained ? retained.pin.point_index : null;
  await page.setViewportSize({ width: 1440, height: 1000 });
  await ready();
  if (!retained) await openStudy(saved.id);
  if (!retained && args['delivery-budgets']) {
    const budgets = args['delivery-budgets'].split(',').map(value => Number(value.trim()));
    await page.locator('#rw-budgets').fill(budgets.join(', '));
    const frontier = await action('#rw-frontier', 'robust.frontier', (allowance + 180) * 1000);
    calculation = frontier.task.result;
    pointIndex = Number(args['delivery-point']);
    requireValue(calculation?.answer?.schema_version === 'ecosci.robust-frontier/1',
      'The original frontier action did not return its retained answer.');
    requireValue(calculation.revision === saved.revision,
      'The delivery frontier did not use the selected saved revision.');
    const point = calculation.answer.points[pointIndex];
    requireValue(point && Array.isArray(point.result?.selected_ids),
      'The explicitly selected frontier point has no feasible retained selection.');
    journal.delivery_frontier = clone(calculation);
  }
  const expected = { study_id: saved.id, run_id: calculation.run_id };
  requireValue(expected.run_id, 'The original calculation has no retained run ID.');
  const getOptions = async (rememberedPoint = null) => {
    const pending = page.waitForResponse(matches('/api/robust-workbench/delivery-options',
      { ...expected, ...(rememberedPoint === null ? {} : { point_index: rememberedPoint }) }));
    await page.locator('#rw-nativeDelivery').click();
    return nativeJSON(await pending, 'Saved decision delivery options');
  };
  let options = await getOptions(retained ? pointIndex : null);
  requireValue(options.study_id === saved.id && options.run_id === calculation.run_id &&
    options.revision === saved.revision, 'Delivery options changed the saved calculation identity.');
  await page.locator('#rw-nativeDeliveryCard').waitFor({ state: 'visible' });
  if (pointIndex !== null && !retained) {
    const pending = page.waitForResponse(matches('/api/robust-workbench/delivery-options',
      { ...expected, point_index: pointIndex }));
    await page.locator('#rw-nativePoint').selectOption(String(pointIndex));
    options = await nativeJSON(await pending, 'Explicit frontier point delivery options');
    requireValue(options.point_index === pointIndex, 'The chosen frontier point changed.');
  }
  const profile = options.profiles?.find(row => row.id === profileId);
  requireValue(profile?.ready === true,
    'The explicitly selected native profile is unavailable: ' +
    (profile?.issues || options.issues || ['Profile is outside the saved calculation']).map(
      item => typeof item === 'object' ? item.message || item.code || JSON.stringify(item) : item).join('; '));
  await page.locator('#rw-nativeProfile').selectOption(profileId);
  const openMap = async () => {
    const pending = page.waitForResponse(matches('/api/robust-workbench/delivery-release',
      { ...expected, profile_id: profileId, ...(pointIndex === null ? {} : { point_index: pointIndex }) }));
    await page.locator('#rw-nativeOpenMap').click();
    const released = await nativeJSON(await pending, 'Original native map release');
    const binding = released.selection?.source_decision;
    requireValue(released.ready && binding?.study_id === saved.id &&
      binding.run_id === calculation.run_id && binding.revision === saved.revision &&
      binding.profile_id === profileId && (binding.point_index ?? null) === pointIndex,
      'The map handoff lost its explicit saved calculation, profile or point.');
    requireValue(released.selection.baseline_run_id === profile.baseline_run_id &&
      canonical(released.selection.scenario_run_ids) === canonical([profile.alternative_run_id]),
      'The map handoff changed the original same-profile native pair.');
    await page.locator('.map-atlas [data-atlas-form]').waitFor({ state: 'visible' });
    return released;
  };
  const release = await openMap();
  const readDraft = () => page.evaluate(key =>
    JSON.parse(sessionStorage.getItem('upstate-atlas-draft:' + key) || 'null'),
    journal.operator_workspace_key);
  const checkDraft = async () => {
    const retained = await readDraft(), selection = retained?.selection;
    requireValue(selection?.baseline_run_id === release.selection.baseline_run_id &&
      canonical(selection?.scenario_run_ids) === canonical(release.selection.scenario_run_ids) &&
      canonical(selection?.source_decision) === canonical(release.selection.source_decision),
      'The original atlas draft changed its native pair or saved decision binding.');
    return retained;
  };
  await checkDraft();
  requireValue(await page.locator('.map-atlas select[name="baseline"]').isDisabled(),
    'The saved decision baseline can be changed independently in the atlas.');
  const alternatives = page.locator('.map-atlas input[name="alternatives"]:checked');
  requireValue(await alternatives.count() === 1 && await alternatives.first().isDisabled(),
    'The saved whole scenario package is not retained as one locked alternative.');
  await shot('08-decision-native-map-draft', '.map-atlas');
  await page.locator('.map-atlas [data-atlas-action="step"][data-step="3"]').click();
  const backlink = page.locator('.map-atlas [data-atlas-action="source-decision"]');
  await backlink.waitFor({ state: 'visible' });
  requireValue(await backlink.getAttribute('data-study-id') === saved.id &&
    await backlink.getAttribute('data-run-id') === calculation.run_id &&
    Number(await backlink.getAttribute('data-revision')) === saved.revision &&
    await backlink.getAttribute('data-profile-id') === profileId,
    'The atlas backlink does not identify its original saved calculation.');
  requireValue((await backlink.getAttribute('data-point-index')) ===
    (pointIndex === null ? null : String(pointIndex)), 'The atlas backlink changed its explicit frontier point.');
  const reopened = page.waitForResponse(matches('/api/robust-workbench/run', expected));
  await backlink.click(); await nativeJSON(await reopened, 'Reopen exact saved calculation from atlas');
  await page.locator('#rw-results').waitFor({ state: 'visible' });
  await page.waitForFunction(({ profile, point }) =>
    document.querySelector('#rw-nativeProfile')?.value === profile &&
    (point === null || document.querySelector('#rw-nativePoint')?.value === String(point)) &&
    document.querySelector('#rw-nativeOpenMap')?.disabled === false,
    { profile: profileId, point: pointIndex });
  options = await getOptions(pointIndex);
  await page.waitForFunction(({ profile, point }) =>
    document.querySelector('#rw-nativeProfile')?.value === profile &&
    (point === null || document.querySelector('#rw-nativePoint')?.value === String(point)) &&
    document.querySelector('#rw-nativeOpenMap')?.disabled === false,
    { profile: profileId, point: pointIndex });
  requireValue(await page.locator('#rw-nativeProfile').inputValue() === profileId,
    'The saved calculation backlink did not retain the explicit native profile.');
  const second = await openMap();
  requireValue(canonical(second.selection.source_decision) === canonical(release.selection.source_decision),
    'Reopening the same saved selection changed its source binding.');
  await page.reload({ waitUntil: 'domcontentloaded' });
  const atlasNav = page.locator('[data-view="map-atlas"]');
  await atlasNav.waitFor({ state: 'visible' });
  if (!(await page.locator('.map-atlas [data-atlas-form]').isVisible())) await atlasNav.click();
  await page.locator('.map-atlas [data-atlas-form]').waitFor({ state: 'visible' });
  const restored = await checkDraft();
  await page.setViewportSize({ width: 390, height: 844 });
  await shot('09-reopened-native-map-draft-mobile', '.map-atlas');
  journal.native_delivery = {
    study_id: saved.id, run_id: calculation.run_id, revision: saved.revision,
    profile_id: profileId, point_index: pointIndex,
    source_decision: clone(release.selection.source_decision),
    baseline_run_id: release.selection.baseline_run_id,
    scenario_run_ids: clone(release.selection.scenario_run_ids),
    restored_draft_step: restored.step, original_backlink: 'reopened',
    mobile_viewport: { width: 390, height: 844 },
  };
}


async function reopenReceivedStudy(receipt) {
  requireValue(receipt?.schema === 'upstate.native-decision-receiving-workflow/v1',
    'Use the completed original native-decision-receiving.json receipt.');
  const key = args.workspace || receipt.restored_workspace_key;
  requireValue(key === receipt.restored_workspace_key,
    'The receiving receipt belongs to its exact restored registered Workspace.');
  const pin = receipt.source_decision, files = receipt.restored_delivery_files;
  requireValue(/^study_[0-9a-f]{32}$/.test(receipt.study_id || '') &&
    /^run_[0-9a-f]{32}$/.test(receipt.run_id || '') &&
    /^[0-9a-f]{64}$/.test(receipt.delivery_id || '') &&
    pin?.study_id === receipt.study_id && pin.run_id === receipt.run_id &&
    pin.revision === receipt.revision && /^[0-9a-f]{64}$/.test(pin.profile_id || '') &&
    (pin.point_index === null || Number.isSafeInteger(pin.point_index) && pin.point_index >= 0) &&
    files && typeof files === 'object',
    'The receipt lacks its exact saved study, calculation, native profile and completed release.');
  args['delivery-profile'] = pin.profile_id;
  args['delivery-point'] = pin.point_index === null ? undefined : String(pin.point_index);
  await changeWorkspace(key); await ready();
  journal.operator_workspace_key = key;
  journal.receiving_operation_id = receipt.operation_id;
  journal.received_study_id = receipt.study_id;
  journal.saved_revision = receipt.revision;
  const nav = page.locator('[data-view="map-atlas"]');
  await nav.click();
  await page.locator('.map-atlas').waitFor({ state: 'visible' });
  const showReleases = page.locator('.map-atlas [data-atlas-action="releases"]');
  if (await showReleases.count()) await showReleases.first().click();
  const open = page.locator('.map-atlas [data-atlas-action="open"][data-id=' +
    JSON.stringify(receipt.delivery_id) + ']').first();
  await open.waitFor({ state: 'visible' });
  const pending = page.waitForResponse(response => {
    const url = new URL(response.url());
    return url.pathname === '/api/item' && url.searchParams.get('kind') === 'deliveries' &&
      url.searchParams.get('id') === receipt.delivery_id;
  });
  await open.click();
  const release = await nativeJSON(await pending, 'Reopen original completed received release');
  requireValue(release.id === receipt.delivery_id && release.state === 'complete' &&
    canonical(release.selection?.source_decision) === canonical(pin),
    'The received atlas changed its original saved Decision binding.');
  for (const [role, descriptor] of Object.entries(files)) {
    requireValue(canonical(release.files?.[role]) === canonical(descriptor),
      'The received release changed its retained file descriptor: ' + role);
  }
  for (const role of ['decision_binding', 'decision_report_html', 'client_report_html', 'native_execution']) {
    const expected = files[role], ticket = release._downloads?.find(item =>
      item.sha256 === expected?.sha256 && item.bytes === expected?.bytes);
    requireValue(ticket && /^\/api\/file\/[0-9a-f]{64}$/.test(ticket.url || ''),
      'The original received release lacks its authenticated ' + role + ' file ticket.');
    const link = page.locator('.map-atlas a[href=' + JSON.stringify(ticket.url + '?download=1') + ']').first();
    requireValue(await link.count() === 1, 'The retained file is absent from the original atlas downloads: ' + role);
    const parents = await link.locator('xpath=ancestor::details').all();
    for (const detail of parents) {
      if (await detail.getAttribute('open') === null) await detail.locator('summary').first().click();
    }
    const downloading = page.waitForEvent('download');
    await link.click();
    const download = await downloading, target = join(output, 'exports', role + '-' + basename(download.suggestedFilename()));
    await download.saveAs(target);
    const bytes = await readFile(target), hash = createHash('sha256').update(bytes).digest('hex');
    requireValue(bytes.length === expected.bytes && hash === expected.sha256,
      'The original restored ' + role + ' download differs from its retained source bytes.');
    journal.exports.push({ role, file: relative(output, target), bytes: bytes.length, sha256: hash,
      delivery_id: release.id, restored_workspace_key: key });
  }
  await shot('10-restored-completed-map-client-release', '.map-atlas');
  await page.setViewportSize({ width: 390, height: 844 });
  await shot('11-restored-map-client-release-mobile', '.map-atlas');
  await page.setViewportSize({ width: 1440, height: 1000 });
  const backlink = page.locator('.map-atlas [data-atlas-action="source-decision"]').first();
  await backlink.waitFor({ state: 'visible' });
  requireValue(await backlink.getAttribute('data-study-id') === receipt.study_id &&
    await backlink.getAttribute('data-run-id') === receipt.run_id &&
    Number(await backlink.getAttribute('data-revision')) === receipt.revision &&
    await backlink.getAttribute('data-profile-id') === pin.profile_id &&
    (await backlink.getAttribute('data-point-index')) ===
      (pin.point_index === null ? null : String(pin.point_index)),
    'The completed release backlink changed its exact saved calculation.');
  const reading = page.waitForResponse(matches('/api/robust-workbench/run',
    { study_id: receipt.study_id, run_id: receipt.run_id }));
  const studyReading = page.waitForResponse(matches('/api/robust-workbench/study',
    { study_id: receipt.study_id, revision: receipt.revision }));
  await backlink.click();
  const run = await nativeJSON(await reading, 'Reopen received original Decision calculation');
  const saved = await nativeJSON(await studyReading, 'Reopen its original saved revision');
  requireValue(run.id === receipt.run_id && run.study_id === receipt.study_id &&
    run.revision === receipt.revision && run.status === 'completed' && run.result &&
    saved.id === receipt.study_id && saved.revision === receipt.revision,
    'The received Decision desk did not reopen the exact completed original calculation.');
  await opened(saved);
  await page.locator('#rw-results').waitFor({ state: 'visible' });
  journal.objective = run.objective || null;
  journal.mode = 'received_saved_calculation';
  journal.received_calculation = { study_id: saved.id, revision: saved.revision, run_id: run.id,
    result_sha256: pin.result_sha256, delivery_id: release.id };
  await exerciseNativeDelivery(saved, null, 0, { run, pin });
  requireValue(canonical(journal.native_delivery.source_decision) === canonical(pin),
    'Reopening the restored map draft changed the completed release source pin.');
  journal.status = 'complete';
}

async function main() {
  await mkdir(join(output, 'exports'), { recursive: true });
  const receiving = args['receiving-receipt'] ? JSON.parse(await readFile(resolve(args['receiving-receipt']), 'utf8')) : null;
  if (receiving) requireValue(!args.experiment && !args.diagnostic && !args.configuration &&
    !args['report-sha256'] && !args['delivery-profile'] && args['delivery-point'] === undefined &&
    args['delivery-budgets'] === undefined,
    '--receiving-receipt reopens its exact restored calculation and profile; keep creation inputs separate.');
  if (!receiving) {
  requireValue(Boolean(args.experiment) !== Boolean(args.diagnostic),
    'Choose exactly one original --experiment or --diagnostic.');
  requireValue(args.configuration, 'Supply --configuration with the explicit decision inputs.');
  requireValue(/^[0-9a-f]{64}$/.test(args.experiment || args.diagnostic), 'Supply an original native source content ID.');
  if (args.diagnostic) requireValue(/^[0-9a-f]{64}$/.test(args['report-sha256'] || ''),
    'Diagnostic receiving requires --report-sha256 from the exact original saved report.');
  else requireValue(!args['report-sha256'], '--report-sha256 applies only to a saved diagnostic.');
  requireValue(['worst_case', 'minimax_regret', 'expected'].includes(args.objective), 'Choose a native robust objective.');
  const allowance = number(Number(args['time-limit']), 'calculation time allowance', { positive: true });
  requireValue(allowance >= 1 && allowance <= 3600, 'Calculation time allowance must be from 1 to 3600 seconds.');
  if (args['delivery-profile']) requireValue(/^[0-9a-f]{64}$/.test(args['delivery-profile']),
    '--delivery-profile must be the exact native profile content ID.');
  if (args['delivery-point'] !== undefined || args['delivery-budgets'] !== undefined) {
    requireValue(args['delivery-profile'] && /^(0|[1-9][0-9]*)$/.test(args['delivery-point'] || '') &&
      Number.isSafeInteger(Number(args['delivery-point'])) && args['delivery-budgets'],
      'An explicit --delivery-point requires --delivery-profile and --delivery-budgets.');
    const parts = args['delivery-budgets'].split(',').map(value => value.trim());
    requireValue(parts.length > 0 && parts.every(value => value && Number.isFinite(Number(value)) && Number(value) >= 0),
      '--delivery-budgets must contain explicit nonnegative finite budget values.');
    const ordered = [...new Set(parts.map(Number))].sort((a,b) => a-b);
    requireValue(Number(args['delivery-point']) < ordered.length,
      '--delivery-point is outside the original sorted unique budget list.');
  }
  }
  const allowance = receiving ? 0 : number(Number(args['time-limit']), 'calculation time allowance', { positive: true });
  const supplied = receiving ? null : JSON.parse(await readFile(resolve(args.configuration), 'utf8'));
  privateURL = (args['url-file'] ? await readFile(args['url-file'], 'utf8') : args.url || process.env.ECO_OPERATOR_URL || '').trim();
  requireValue(privateURL, 'Supply the original private operator URL via --url-file, --url or ECO_OPERATOR_URL.');
  let parsed; try { parsed = new URL(privateURL); } catch { throw Error('The private operator URL is not valid.'); }
  requireValue(['http:', 'https:'].includes(parsed.protocol), 'The operator URL must use HTTP or HTTPS.');
  origin = parsed.origin; capability = new URLSearchParams(parsed.hash.slice(1)).get('token') || '';
  browser = await chromium.launch({ headless: !args.headed, ...(args['browser-channel'] ? { channel: args['browser-channel'] } : {}) });
  context = await browser.newContext({ viewport: { width: 1440, height: 1000 }, acceptDownloads: true,
    ...(args.video ? { recordVideo: { dir: join(output, 'video'), size: { width: 1440, height: 1000 } } } : {}) });
  page = await context.newPage(); page.setDefaultTimeout(60000);
  page.on('pageerror', error => journal.browser_errors.push(redact(error.message)));
  page.on('response', response => { void observeResponse(response); });
  await page.goto(privateURL, { waitUntil: 'domcontentloaded' });
  await page.locator('#workspace-select').waitFor({ state: 'visible' });
  if (receiving) { await reopenReceivedStudy(receiving); return; }
  await findSource();
  journal.operator_workspace_key = await page.locator('#workspace-select').inputValue();
  const configureSelector = args.diagnostic ? '#rw-configureDiagnostic' : '#rw-configureExperiment';
  const sourceSelector = args.diagnostic ? '#rw-diagnostics' : '#rw-experiments';
  const sourceOperation = args.diagnostic ? 'diagnostic' : 'experiment';
  const sourceField = args.diagnostic ? 'diagnostic_id' : 'experiment_id';
  const sourceId = args.diagnostic || args.experiment;
  if (!(await page.locator(configureSelector).isVisible())) await page.locator('#rw-importToggle').click();
  await page.locator(sourceSelector).selectOption(sourceId);
  const loading = page.waitForResponse(matches('/api/robust-workbench/' + sourceOperation, { [sourceField]: sourceId }));
  await page.locator(configureSelector).click();
  const native = await nativeJSON(await loading, 'Original ' + sourceOperation + ' configuration');
  requireValue(native[sourceField] === sourceId, 'The source response changed the selected native ID.');
  if (args.diagnostic) requireValue(native.report_sha256 === args['report-sha256'],
    'The saved diagnostic report advanced. Review its current explicit configuration and rerun with the intended report SHA.');
  const configured = prepareConfiguration(native.configuration, supplied);
  journal.native_source = clone(configured.source);
  journal.decision_configuration = clone(configured); delete journal.decision_configuration.cells;
  if (args.diagnostic) {
    journal.diagnostic_coverage = clone(native.coverage);
    journal.diagnostic_common_support = clone(native.common_support);
    journal.diagnostic_results_state = native.results_state;
  } else journal.original_summary_sha256 = createHash('sha256').update(canonical(native.summary)).digest('hex');
  await page.locator('#rw-editor').waitFor({ state: 'visible' });
  await page.locator('details').filter({ has: page.locator('#rw-advanced') }).locator('summary').click();
  await page.locator('#rw-advanced').fill(JSON.stringify(configured, null, 2)); await page.locator('#rw-applyAdvanced').click();
  await page.locator('#rw-title').fill(configured.title); await page.locator('#rw-costUnitsInput').fill(configured.cost_units);
  for (const metric of configured.metrics) {
    await page.getByLabel(metric.id + ' scale', { exact: true }).fill(String(metric.scale));
    await page.getByLabel(metric.id + ' weight', { exact: true }).fill(String(metric.weight));
  }
  for (const candidate of configured.candidates) {
    await page.getByLabel(candidate.id + ' cost', { exact: true }).fill(String(candidate.cost));
    await page.getByLabel(candidate.id + ' capacity', { exact: true }).fill(String(candidate.capacity));
  }
  await shot('01-native-decision-configuration', '#rw-editor');
  const prepared = await action('#rw-save', args.diagnostic ? 'robust.diagnostic.prepare' : 'robust.experiment.prepare');
  if (args.diagnostic) requireValue(
    prepared.request.payload.diagnostic_id === args.diagnostic &&
    prepared.request.payload.report_sha256 === args['report-sha256'],
    'The queued preparation lost the exact selected diagnostic report revision.');
  requireValue(!('cells' in prepared.request.payload.configuration), 'The browser submitted constructed cells instead of using the native receiver.');
  const created = prepared.task.result;
  requireValue(created?.id && created.study?.cells?.length, 'Native preparation did not produce its retained study and outcome cells.');
  requireValue(created.study.cells.length === configured.candidates.length * configured.profiles.length, 'The native study does not retain the requested complete candidate/profile matrix.');
  for (const cell of created.study.cells) {
    requireValue(cell.source?.baseline_run_id && cell.source?.alternative_run_id, 'A native outcome cell is missing its original paired run identities.');
  }
  if (args.diagnostic) {
    const source = created.study.source || {}, binding = source.diagnostic_binding;
    requireValue(source.pair_contract === 'ES26/diagnostic-common-support/v1' &&
      source.diagnostic_id === args.diagnostic && source.diagnostic_report_sha256 === args['report-sha256'],
      'The created study lost the exact diagnostic provenance.');
    requireValue(binding?.schema === 'upstate.decision-diagnostic-binding/v1' &&
      binding.diagnostic_id === args.diagnostic && binding.report_sha256 === args['report-sha256'] &&
      binding.report?.sha256 === args['report-sha256'],
      'The created study lacks its retained exact-byte diagnostic revision.');
    journal.diagnostic_binding = clone(binding);
  }
  journal.created_study_id = created.id; journal.created_revision = created.revision;
  journal.native_cells_sha256 = createHash('sha256').update(canonical(created.study.cells)).digest('hex');
  await opened(created); await shot('02-prepared-native-study', '#rw-editor');
  const initialProject = await exportFile('#rw-exportProject', 'robust.project.export', 'json');
  journal.initial_project_export_task_id = initialProject.task.id;
  await page.locator('#rw-title').fill(created.study.title + ' · prepared decision revision');
  const revised = await action('#rw-save', 'robust.study.revise'), saved = revised.task.result;
  requireValue(saved.id === created.id && saved.revision > created.revision, 'The native revision did not advance the saved study.');
  requireValue(canonical(saved.study.cells) === canonical(created.study.cells), 'A title revision changed the retained native outcome cells.');
  journal.saved_revision = saved.revision; await opened(saved);
  await page.locator('#rw-objective').selectOption(args.objective);
  await page.locator('#rw-timeLimit').fill(String(allowance));
  const solved = await action('#rw-solve', 'robust.solve', (allowance + 180) * 1000);
  requireValue(solved.task.result?.answer && solved.task.result.revision === saved.revision, 'The calculation did not retain its exact saved revision and answer.');
  journal.solve = clone(solved.task.result);
  await page.locator('#rw-results').waitFor({ state: 'visible' });
  await shot('03-native-decision-results', '#rw-results');
  const retried = await action('#rw-solve', 'robust.solve', (allowance + 180) * 1000);
  requireValue(retried.request.operation_id === solved.request.operation_id && retried.task.id === solved.task.id && retried.task.result.run_id === solved.task.result.run_id,
    'Retrying the unchanged completed calculation did not reopen the same original operation and run.');
  journal.completed_operation_retry = { task_id: retried.task.id, run_id: retried.task.result.run_id, same_operation: true };
  await exportFile('#rw-reportHtml', 'robust.report.export', 'html');
  await exportFile('#rw-reportCsv', 'robust.report.export', 'csv');
  requireValue(Array.isArray(solved.task.result.answer.result?.selected_ids), 'The supplied decision configuration has no feasible retained selection. Its native diagnostic and reports are saved; adjust the declared constraints and run a new decision configuration.');
  await exportFile('#rw-exportSelection', 'robust.selection.export', 'json');
  const projectExport = await exportFile('#rw-exportProject', 'robust.project.export', 'json');
  requireValue(projectExport.task.id !== initialProject.task.id, 'Exporting after a new revision and calculation reopened the earlier project snapshot.');
  const project = JSON.parse(projectExport.bytes.toString('utf8'));
  requireValue(project.schema_version === 'ecosci.robust-project/1' && project.sha256 && project.payload, 'The downloaded file is not the original complete robust project.');
  journal.project_sha256 = project.sha256;
  await shot('04-retained-study-exports', '#rw-operations');
  await page.locator('#rw-importToggle').click();
  await page.locator('#rw-studyFile').setInputFiles(projectExport.path);
  const received = await action('#rw-importStudy', 'robust.project.receive');
  const restored = received.task.result;
  requireValue(restored?.id && restored.id !== saved.id, 'Receiving the portable project did not create its independent retained study.');
  requireValue(canonical(restored.study) === canonical(saved.study), 'The received project changed the original saved decision inputs.');
  requireValue(restored.runs?.some(run => run.result && canonical(run.result) === canonical(solved.task.result.answer)),
    'The received project did not retain the completed native calculation answer.');
  journal.received_study_id = restored.id; await opened(restored);
  await page.reload({ waitUntil: 'domcontentloaded' }); await ready();
  const reopened = await openStudy(restored.id);
  requireValue(canonical(reopened.study) === canonical(saved.study), 'Reopening the received study changed its saved decision inputs.');
  await page.locator('details').filter({ has: page.locator('#rw-history') }).locator('summary').click();
  const history = page.locator('#rw-history button').filter({ hasText: 'View result' });
  await history.first().click(); await page.locator('#rw-results').waitFor({ state: 'visible' });
  await shot('05-reopened-portable-study', '#rw-results');
  await shot('06-complete-decision-workspace');
  await page.setViewportSize({ width: 390, height: 844 });
  await shot('07-reopened-decision-mobile', '#rw-results');
  journal.mobile_viewport = { width: 390, height: 844 };
  await exerciseNativeDelivery(saved, solved, allowance);
  journal.status = 'complete';
}
try { await main(); }
catch (error) {
  journal.status = 'failed'; journal.error = redact(error?.stack || error);
  if (page && !page.isClosed()) try { await shot('failure-state'); } catch {}
  process.exitCode = 1;
}
finally {
  if (context) await context.close().catch(() => {});
  if (args.video && page?.video()) {
    try { const original = await page.video().path(); const named = join(output, 'operator-journey.webm'); await rename(original, named); journal.video = relative(output, named); }
    catch (error) { journal.video_error = redact(error.message); }
  }
  if (browser) await browser.close().catch(() => {});
  journal.finished_at = new Date().toISOString();
  await mkdir(output, { recursive: true });
  await writeFile(join(output, 'journey.json'), JSON.stringify(journal, null, 2) + '\n');
  process.stdout.write(JSON.stringify({ status: journal.status, output, study_id: journal.created_study_id || null, received_study_id: journal.received_study_id || null, error: journal.error ? redact(journal.error.split('\n')[0]) : null }) + '\n');
}
